"""TaskWeaver plugin: dominusnode_usage (generated by dominusnode_taskweaver.generate_plugins)."""

from taskweaver.plugin import Plugin, register_plugin

from dominusnode_taskweaver.runtime import run


@register_plugin
class DominusNodeUsage(Plugin):
    def __call__(self, from_=None, to=None) -> str:
        return run(self, "usage", {"from": from_, "to": to})
